#!/usr/bin/env python3
"""Compute Fleiss' Kappa and Effective-K with answer normalization."""

import json
import os
import sys
import glob
import re
import numpy as np
from collections import Counter


def normalize_answer_folio(raw):
    """Normalize FOLIO/ProofWriter answer to True/False/Unknown."""
    s = raw.strip().lower()
    # Remove latex artifacts
    s = re.sub(r'\\text\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\textbf\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\[a-z]+', '', s)
    s = s.replace('{', '').replace('}', '').strip()

    # Check for True
    if s in ('true', 'yes', 'correct'):
        return 'True'
    if 'conclusion is true' in s or 'statement is true' in s:
        return 'True'
    if s.startswith('true') and len(s) < 30:
        return 'True'

    # Check for False
    if s in ('false', 'no', 'incorrect'):
        return 'False'
    if 'conclusion is false' in s or 'statement is false' in s:
        return 'False'
    if s.startswith('false') and len(s) < 30:
        return 'False'

    # Check for Unknown
    if s in ('unknown', 'uncertain', 'undetermined', 'cannot be determined',
             'not enough information', 'insufficient information'):
        return 'Unknown'
    if 'unknown' in s or 'uncertain' in s or 'cannot be determined' in s:
        return 'Unknown'
    if 'not enough' in s or 'insufficient' in s or 'undetermined' in s:
        return 'Unknown'

    # If contains "true" or "false" as substring, map accordingly
    if 'true' in s and 'false' not in s and 'not true' not in s:
        return 'True'
    if 'false' in s and 'true' not in s and 'not false' not in s:
        return 'False'

    # Default to Unknown for ambiguous answers
    return 'Unknown'


def normalize_answer_logiqa(raw):
    """Normalize LogiQA answer to A/B/C/D."""
    s = raw.strip().upper()
    # Extract single letter
    m = re.match(r'^([A-D])\b', s)
    if m:
        return m.group(1)
    m = re.search(r'\b([A-D])\b', s)
    if m:
        return m.group(1)
    return raw.strip()


def normalize_answer_pw(raw):
    """Normalize ProofWriter answer to True/False/Unknown."""
    s = raw.strip().lower()
    # Remove latex
    s = re.sub(r'\\text\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\textbf\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\[a-z]+', '', s)
    s = s.replace('{', '').replace('}', '').replace('\\', '').strip()

    if s in ('true', 'yes'):
        return 'True'
    if s in ('false', 'no'):
        return 'False'
    if s in ('unknown', 'uncertain'):
        return 'Unknown'

    # Check substrings
    if 'true' in s and 'false' not in s:
        return 'True'
    if 'false' in s and 'true' not in s:
        return 'False'
    if 'unknown' in s or 'uncertain' in s:
        return 'Unknown'

    # For PW, non-standard answers that are actual propositions (like "Fiona is furry")
    # These should be treated as True (the model is asserting the conclusion)
    # But this is ambiguous - let's check if it looks like a proposition
    if len(s) > 5 and not any(c in s for c in ['?', 'cannot', 'not enough']):
        return 'True'

    return 'Unknown'


def detect_dataset(dname, categories, data):
    """Detect dataset type from directory name and answer patterns."""
    dl = dname.lower()
    if 'logiqa' in dl:
        return 'logiqa'
    if 'pw' in dl or 'proofwriter' in dl:
        return 'proofwriter'
    if 'folio' in dl:
        return 'folio'

    # Check answer patterns
    if set(categories) <= {'A', 'B', 'C', 'D'}:
        return 'logiqa'

    return 'folio'  # default


def load_traces_from_intermediates(intermediates_dir):
    """Load per-problem trace answers from intermediate JSON files."""
    data = []
    files = sorted(glob.glob(os.path.join(intermediates_dir, "*.json")))
    for fpath in files:
        with open(fpath) as f:
            d = json.load(f)

        problem_id = d.get("problem", {}).get("id", os.path.basename(fpath))
        sica = d.get("sica_result", {})
        traces = sica.get("traces", [])

        answers = []
        for t in traces:
            ans = t.get("answer", t.get("extracted_answer", ""))
            if ans:
                answers.append(ans)

        data.append({
            "problem_id": problem_id,
            "answers": answers,
            "n_traces": len(traces),
            "n_valid": len(answers)
        })
    return data


def compute_fleiss_kappa(data, normalizer=None):
    """
    Compute Fleiss' kappa from per-problem answer lists.
    """
    if normalizer:
        for item in data:
            item["answers"] = [normalizer(a) for a in item["answers"]]

    # Get all unique answer categories
    all_answers = set()
    for item in data:
        for ans in item["answers"]:
            all_answers.add(ans)
    categories = sorted(all_answers)

    n = len(data)
    k = len(categories)
    cat_idx = {c: i for i, c in enumerate(categories)}

    # Build rating matrix: n_problems x n_categories
    matrix = np.zeros((n, k), dtype=int)
    for i, item in enumerate(data):
        for ans in item["answers"]:
            if ans in cat_idx:
                matrix[i, cat_idx[ans]] += 1

    K_total = matrix.sum(axis=1)
    N = n

    total_ratings = matrix.sum()
    if total_ratings == 0:
        return None
    p_j = matrix.sum(axis=0) / total_ratings

    P_i = np.zeros(N)
    for i in range(N):
        Ki = K_total[i]
        if Ki <= 1:
            P_i[i] = 1.0
        else:
            P_i[i] = (np.sum(matrix[i] ** 2) - Ki) / (Ki * (Ki - 1))

    P_bar = np.mean(P_i)
    P_e = np.sum(p_j ** 2)

    if P_e == 1.0:
        kappa = 1.0
    else:
        kappa = (P_bar - P_e) / (1.0 - P_e)

    K_median = int(np.median(K_total))
    if kappa > 0:
        eff_k = K_median / (1 + (K_median - 1) * kappa)
    else:
        eff_k = float(K_median)

    unanimous = sum(1 for i in range(N) if np.max(matrix[i]) == K_total[i])
    unanimous_rate = unanimous / N if N > 0 else 0

    cat_dist = {}
    for j, cat in enumerate(categories):
        cat_dist[cat] = int(matrix[:, j].sum())

    return {
        "fleiss_kappa": round(float(kappa), 4),
        "eff_k": round(float(eff_k), 3),
        "K_median": int(K_median),
        "n_problems": N,
        "n_categories": k,
        "categories": categories,
        "category_totals": cat_dist,
        "unanimous_rate": round(float(unanimous_rate), 4),
        "P_bar": round(float(P_bar), 4),
        "P_e": round(float(P_e), 4),
        "mean_K_per_problem": round(float(np.mean(K_total)), 2),
        "min_K": int(np.min(K_total)),
        "max_K": int(np.max(K_total)),
    }


def main():
    base = "/root/symb_invariant_consensus/results"
    output = {}

    normalizers = {
        'folio': normalize_answer_folio,
        'logiqa': normalize_answer_logiqa,
        'proofwriter': normalize_answer_pw,
    }

    for dname in sorted(os.listdir(base)):
        dpath = os.path.join(base, dname)
        if not os.path.isdir(dpath):
            continue

        intermediates = os.path.join(dpath, "intermediates")
        if not os.path.isdir(intermediates) or len(os.listdir(intermediates)) == 0:
            print(f"SKIP {dname}: no intermediates", file=sys.stderr)
            continue

        data = load_traces_from_intermediates(intermediates)
        if not data:
            print(f"SKIP {dname}: empty data", file=sys.stderr)
            continue

        # First pass: get raw categories to detect dataset
        raw_cats = set()
        for item in data:
            for ans in item["answers"]:
                raw_cats.add(ans)

        dataset_type = detect_dataset(dname, raw_cats, data)
        normalizer = normalizers.get(dataset_type, normalize_answer_folio)

        result = compute_fleiss_kappa(data, normalizer)
        if result is None:
            print(f"SKIP {dname}: no ratings", file=sys.stderr)
            continue

        result["dataset_type"] = dataset_type
        result["dir_name"] = dname
        result["raw_category_count"] = len(raw_cats)
        output[dname] = result

        print(f"{dname}: kappa={result['fleiss_kappa']:.4f} eff_k={result['eff_k']:.3f} "
              f"n={result['n_problems']} K={result['K_median']} "
              f"unanimous={result['unanimous_rate']:.4f} "
              f"cats={result['categories']} (raw={len(raw_cats)}) "
              f"type={dataset_type}",
              file=sys.stderr)

    json.dump(output, sys.stdout, indent=2)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compute Fleiss' Kappa and Effective-K with answer normalization.
Empty/unparseable answers are mapped to 'Unknown' (FOLIO/PW) to maintain K=12."""

import json
import os
import sys
import glob
import re
import numpy as np
from collections import Counter


def normalize_answer_folio(raw):
    """Normalize FOLIO answer to True/False/Unknown."""
    if not raw or not raw.strip():
        return 'Unknown'
    s = raw.strip().lower()
    s = re.sub(r'\\text\w*\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\[a-z]+', '', s)
    s = s.replace('{', '').replace('}', '').replace('\\', '').strip()
    s = re.sub(r'[.*]$', '', s).strip()

    if s in ('true', 'yes', 'correct'):
        return 'True'
    if 'conclusion is true' in s or 'statement is true' in s:
        return 'True'
    if s.startswith('true'):
        return 'True'

    if s in ('false', 'no', 'incorrect'):
        return 'False'
    if 'conclusion is false' in s or 'statement is false' in s:
        return 'False'
    if s.startswith('false'):
        return 'False'

    if s in ('unknown', 'uncertain', 'undetermined', 'cannot be determined'):
        return 'Unknown'
    if 'unknown' in s or 'uncertain' in s or 'cannot be determined' in s:
        return 'Unknown'
    if 'not enough' in s or 'insufficient' in s or 'undetermined' in s:
        return 'Unknown'

    if 'true' in s and 'false' not in s and 'not true' not in s:
        return 'True'
    if 'false' in s and 'true' not in s and 'not false' not in s:
        return 'False'

    return 'Unknown'


def normalize_answer_logiqa(raw):
    """Normalize LogiQA answer to A/B/C/D."""
    if not raw or not raw.strip():
        return '_invalid'
    s = raw.strip()
    m = re.match(r'^([A-Da-d])\b', s)
    if m:
        return m.group(1).upper()
    m = re.search(r'\(([A-Da-d])\)', s)
    if m:
        return m.group(1).upper()
    m = re.search(r'answer\s*(?:is|:)\s*([A-Da-d])\b', s, re.IGNORECASE)
    if m:
        return m.group(1).upper()
    return '_invalid'


def normalize_answer_pw(raw):
    """Normalize ProofWriter answer to True/False/Unknown."""
    if not raw or not raw.strip():
        return 'Unknown'
    s = raw.strip().lower()
    s = re.sub(r'\\text\w*\s*\{[^}]*\}', '', s)
    s = re.sub(r'\\[a-z]+', '', s)
    s = s.replace('{', '').replace('}', '').replace('\\', '').strip()

    if s in ('true', 'yes'):
        return 'True'
    if s in ('false', 'no'):
        return 'False'
    if s in ('unknown', 'uncertain'):
        return 'Unknown'

    if 'true' in s and 'false' not in s:
        return 'True'
    if 'false' in s and 'true' not in s:
        return 'False'
    if 'unknown' in s or 'uncertain' in s:
        return 'Unknown'

    # Proposition-like answers from PW (model asserts conclusion text)
    if len(s) > 5 and not any(w in s for w in ['?', 'cannot', 'not enough']):
        return 'True'

    return 'Unknown'


def detect_dataset(dname):
    dl = dname.lower()
    if 'logiqa' in dl:
        return 'logiqa'
    if 'pw' in dl or 'proofwriter' in dl:
        return 'proofwriter'
    return 'folio'


def load_traces_from_intermediates(intermediates_dir, normalizer):
    """Load per-problem trace answers from intermediate JSON files."""
    data = []
    files = sorted(glob.glob(os.path.join(intermediates_dir, "*.json")))
    for fpath in files:
        with open(fpath) as f:
            d = json.load(f)

        problem_id = d.get("problem", {}).get("id", os.path.basename(fpath))
        sica = d.get("sica_result", {})
        traces = sica.get("traces", [])

        raw_answers = []
        for t in traces:
            raw = t.get("answer", t.get("extracted_answer", ""))
            raw_answers.append(raw)

        # Normalize all answers (empty ones get mapped to Unknown/invalid)
        answers = [normalizer(a) for a in raw_answers]

        data.append({
            "problem_id": problem_id,
            "answers": answers,
            "n_traces": len(traces),
        })
    return data


def compute_fleiss_kappa(data, valid_categories=None):
    """Compute Fleiss' kappa. If valid_categories set, only count those."""
    all_answers = set()
    for item in data:
        for ans in item["answers"]:
            all_answers.add(ans)

    if valid_categories:
        categories = sorted(valid_categories)
    else:
        categories = sorted(all_answers)

    n = len(data)
    k = len(categories)
    cat_idx = {c: i for i, c in enumerate(categories)}

    matrix = np.zeros((n, k), dtype=int)
    for i, item in enumerate(data):
        for ans in item["answers"]:
            if ans in cat_idx:
                matrix[i, cat_idx[ans]] += 1

    K_total = matrix.sum(axis=1)
    N = n

    total_ratings = matrix.sum()
    if total_ratings == 0:
        return None
    p_j = matrix.sum(axis=0) / total_ratings

    P_i = np.zeros(N)
    for i in range(N):
        Ki = K_total[i]
        if Ki <= 1:
            P_i[i] = 1.0
        else:
            P_i[i] = (np.sum(matrix[i] ** 2) - Ki) / (Ki * (Ki - 1))

    P_bar = np.mean(P_i)
    P_e = np.sum(p_j ** 2)

    if P_e == 1.0:
        kappa = 1.0
    else:
        kappa = (P_bar - P_e) / (1.0 - P_e)

    K_median = int(np.median(K_total))
    if kappa > 0:
        eff_k = K_median / (1 + (K_median - 1) * kappa)
    else:
        eff_k = float(K_median)

    unanimous = sum(1 for i in range(N) if K_total[i] > 0 and np.max(matrix[i]) == K_total[i])
    unanimous_rate = unanimous / N if N > 0 else 0

    cat_dist = {}
    for j, cat in enumerate(categories):
        cat_dist[cat] = int(matrix[:, j].sum())

    return {
        "fleiss_kappa": round(float(kappa), 4),
        "eff_k": round(float(eff_k), 3),
        "K_median": int(K_median),
        "n_problems": N,
        "n_categories": k,
        "categories": categories,
        "category_totals": cat_dist,
        "unanimous_rate": round(float(unanimous_rate), 4),
        "P_bar": round(float(P_bar), 4),
        "P_e": round(float(P_e), 4),
        "mean_K_per_problem": round(float(np.mean(K_total)), 2),
        "min_K": int(np.min(K_total)),
        "max_K": int(np.max(K_total)),
    }


def main():
    base = "/root/symb_invariant_consensus/results"
    output = {}

    normalizers = {
        'folio': normalize_answer_folio,
        'logiqa': normalize_answer_logiqa,
        'proofwriter': normalize_answer_pw,
    }

    valid_cats = {
        'folio': {'True', 'False', 'Unknown'},
        'logiqa': {'A', 'B', 'C', 'D'},
        'proofwriter': {'True', 'False', 'Unknown'},
    }

    for dname in sorted(os.listdir(base)):
        dpath = os.path.join(base, dname)
        if not os.path.isdir(dpath):
            continue

        intermediates = os.path.join(dpath, "intermediates")
        if not os.path.isdir(intermediates) or len(os.listdir(intermediates)) == 0:
            print(f"SKIP {dname}: no intermediates", file=sys.stderr)
            continue

        dataset_type = detect_dataset(dname)
        normalizer = normalizers[dataset_type]

        data = load_traces_from_intermediates(intermediates, normalizer)
        if not data:
            print(f"SKIP {dname}: empty data", file=sys.stderr)
            continue

        result = compute_fleiss_kappa(data, valid_cats.get(dataset_type))
        if result is None:
            print(f"SKIP {dname}: no ratings", file=sys.stderr)
            continue

        result["dataset_type"] = dataset_type
        result["dir_name"] = dname
        output[dname] = result

        print(f"{dname}: kappa={result['fleiss_kappa']:.4f} eff_k={result['eff_k']:.3f} "
              f"n={result['n_problems']} K={result['K_median']} "
              f"unanimous={result['unanimous_rate']:.4f} "
              f"cats={result['categories']} type={dataset_type}",
              file=sys.stderr)

    json.dump(output, sys.stdout, indent=2)


if __name__ == "__main__":
    main()
